package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RequirePushedAuthorizationRequestsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property require pushed authorization requests of oauth client ")
  void test_require_pushed_authorization_requests_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> RequirePushedAuthorizationRequestsVO.tryFrom(null));
    Assertions.assertEquals(true,
        RequirePushedAuthorizationRequestsVO.from(true).isRequirePushedAuthorizationRequests());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RequirePushedAuthorizationRequestsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]",
        RequirePushedAuthorizationRequestsVO.from(true).toString());
  }
}
